def fizzbuzz(n: int) -> list[str | int]:
    """
    Returns a list of FizzBuzz values up to n.
    """
    result = []
    for i in range(1, n + 1):
        output = ""
        if i % 3 == 0:
            output += "Fizz"
        if i % 5 == 0:
            output += "Buzz"

        if output:
            result.append(output)
        else:
            result.append(i)
    return result

if __name__ == '__main__':
    # Test case: up to 15
    test_n = 15
    output = fizzbuzz(test_n)
    print(f"FizzBuzz list up to {test_n}: {output}")
